package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.CentroCusto; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/centros-custo") public class CentroCustoRestController { final CentroCustoApplicationService s; public CentroCustoRestController(CentroCustoApplicationService s){this.s=s;} @PostMapping public CentroCusto criar(@Valid @RequestBody CentroCustoRequest r){return s.criar(r);} @GetMapping public List<CentroCusto> listar(){return s.listar();} }